# usage: vm.sh run SCRIPTFILE | vm.sh push SRC_TARBALL | vm.sh wait
SSHO="-o BatchMode=yes -o ConnectTimeout=10 -o ServerAliveInterval=30 -p 2222 -i $HOME/.ssh/vpt1_ref_ed25519"
case "$1" in
wait) for i in $(seq 1 60); do ssh $SSHO testuser@127.0.0.1 true 2>/dev/null && echo up && exit 0; sleep 5; done; echo timeout; exit 1;;
run) ssh $SSHO testuser@127.0.0.1 bash -s < "$2";;
push) ssh $SSHO testuser@127.0.0.1 "rm -rf ~/vpt && mkdir ~/vpt && tar -C ~/vpt -xf -" < "$2";;
esac

