		u64 add = div_u64((now_ns - b->last_ns) * rate, 1000000ULL);

		b->milli = min(cap, b->milli + add);
	}
	if (!b->last_ns || now_ns > b->last_ns)
		b->last_ns = now_ns;
	if (b->milli < 1000)
		return false;
	b->milli -= 1000;
	return true;
}

