{
	const size_t HOST_CAP = VPT1_HOST_MEM_BUDGET;
	const size_t steps[] = { 1024UL * 1024UL, 4096, 64, 1 };
	struct vpt1_snapshot *s = kzalloc(sizeof(*s), GFP_KERNEL);
	struct vpt1_cfg_accounting b, a, b7;
	struct vpt1_gw *v = NULL, *f[8] = {};
	size_t held[8] = {}, C;
	u64 T = ktime_get_boottime_ns();
	unsigned int i, k;
	int err;

	if (!s)
		return;
	EXPECT(t, vpt1_host_mem_used() == 0);
	v = new_gw(t, T, NULL);
	for (i = 0; i < 8; i++)
		f[i] = new_gw(t, T, NULL);
	if (!v || !f[7])
		goto out;
	snap_base(s);
	EXPECT(t, !stage_commit(v, 1, s, T, NULL));
	acc_get(v, &b);
	C = b.current_charge;
	pr_info("EXT: C=%zu charged=%zu gw_mem=%zu host=%zu\n", C, b.charged, b.gw_mem, b.host_mem);
	EXPECT(t, C > 0 && b.gw_mem == C && b.charged == C && b.host_mem == C && !b.staged_charge);

	/* (2) stage, then re-VALIDATE replacing the staged one: only one staged copy counts. */
	EXPECT(t, !do_validate(v, 2, s));
	acc_get(v, &a);
	EXPECT(t, a.staged_charge == C && a.gw_mem == 2 * C && a.host_mem == 2 * C);
	EXPECT(t, !do_validate(v, 3, s));
	acc_get(v, &a);
	EXPECT(t, a.staged_charge == C && a.gw_mem == 2 * C && a.host_mem == 2 * C &&
		   a.charged == 2 * C);
	/* VALIDATE that fails after the reserve (duplicate rule id -> ACL create -EEXIST). */
	acc_get(v, &b);
	s->rules[1].id = 1;
	err = do_validate(v, 4, s);
	s->rules[1].id = 2;
	EXPECT(t, err == -EEXIST);
	acc_get(v, &a);
	EXPECT(t, acc_same(&a, &b));
	pr_info("EXT: acl-fail err=%d gw_mem %zu->%zu host %zu->%zu charged %zu->%zu\n", err,
		b.gw_mem, a.gw_mem, b.host_mem, a.host_mem, b.charged, a.charged);

	/* (1) fill the host ceiling with raw reserves on OTHER gateways, then VALIDATE. */
	for (k = 0; k < ARRAY_SIZE(steps); k++)
		for (i = 0; i < 8; i++)
			while (vpt1_gw_mem_reserve(f[i], steps[k]))
				held[i] += steps[k];
	EXPECT(t, vpt1_host_mem_used() == HOST_CAP);
	acc_get(v, &b);
	acc_get(f[7], &b7);
	err = do_validate(v, 5, s);
	EXPECT(t, err == -ENOSPC);
	acc_get(v, &a);
	EXPECT(t, acc_same(&a, &b));
	EXPECT(t, vpt1_host_mem_used() == HOST_CAP);
	pr_info("EXT: host-full err=%d gw_mem %zu->%zu host %zu->%zu charged %zu->%zu\n", err,
		b.gw_mem, a.gw_mem, b.host_mem, a.host_mem, b.charged, a.charged);
	/* A gateway with no config at all, same ceiling. */
	vpt1_gw_lock(f[7]);
	err = vpt1_gw_validate(f[7], 1, s);
	vpt1_gw_unlock(f[7]);
	EXPECT(t, err == -ENOSPC);
	acc_get(f[7], &a);
	EXPECT(t, a.charged == 0 && a.gw_mem == held[7] && a.host_mem == HOST_CAP && !a.staged_charge);
	for (i = 0; i < 8; i++) {
		size_t left = held[i];

		for (k = 0; k < ARRAY_SIZE(steps); k++)
			while (left >= steps[k] && (k == ARRAY_SIZE(steps) - 1 || left >= steps[k])) {
				vpt1_gw_mem_release(f[i], steps[k]);
				left -= steps[k];
				if (k != ARRAY_SIZE(steps) - 1 && left < steps[k])
					break;
			}
		EXPECT(t, left == 0);
	}
	/* Transient: the same VALIDATE succeeds once the host drains. */
	EXPECT(t, vpt1_host_mem_used() == 2 * C);
	EXPECT(t, !do_validate(v, 5, s));

	/* (3) commit N then N+1; the retired config's bytes return after rcu_barrier. */
	for (i = 5; i <= 6; i++) {
		if (i == 6)
			EXPECT(t, !do_validate(v, 6, s));
		EXPECT(t, !do_commit(v, i, T));
		acc_get(v, &a);
		EXPECT(t, a.gw_mem >= C && a.gw_mem <= 2 * C);
		rcu_barrier();
		acc_get(v, &a);
		pr_info("EXT: after commit %u+rcu_barrier gw_mem=%zu host=%zu charged=%zu retired=%u C=%zu\n",
			i, a.gw_mem, a.host_mem, a.charged, a.retired, C);
		EXPECT(t, a.gw_mem == C && a.host_mem == C && a.charged == C && a.retired == 0);
	}
out:
	for (i = 0; i < 8; i++)
		if (f[i])
			end_gw(t, f[i]);
	if (v)
		end_gw(t, v);
	rcu_barrier();
	pr_info("EXT: final host=%zu\n", vpt1_host_mem_used());
	EXPECT(t, vpt1_host_mem_used() == 0); /* (4) */
	kfree(s);
}

content.content:
run) ssh $SSHO testuser@127.0.0.1 bash -s < "$2";;
push) ssh $SSHO testuser@127.0.0.1 "rm -rf ~/vpt && mkdir ~/vpt && tar --warning=no-unknown-keyword -C ~/vpt -xf - 2>/dev/null" < "$2";;
put) ssh $SSHO testuser@127.0.0.1 "cat > $3" < "$2";;
esac
